using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Threading;

namespace PixelForge {
public sealed partial class MainWindow {
    TextBox stabilityStrength=Box("2"),stableColors=Box("64"),referenceThreshold=Box("56");
    void AddSpriteStabilizationControls(Panel panel){Label(panel,"СТАБИЛИЗАЦИЯ АНИМАЦИИ");Row(panel,"Сила: 1…3",stabilityStrength);Row(panel,"Общая палитра: 16…256",stableColors);Row(panel,"Порог смены цвета: 8…128",referenceThreshold);Add(panel,"Убрать рябь во всех кадрах",async()=>await StabilizeSprites());panel.Children.Add(new TextBlock {Text="Первый кадр сохраняется точно; неподвижные детали удерживают его рисунок. Порог 56 подавляет слабую смену оттенков; заметные изменения и движение проверяются отдельно. Начните с силы 2. Стирание и прозрачность сохраняются; Ctrl+Z отменяет обработку целиком.",TextWrapping=TextWrapping.Wrap,Foreground=Brushes.LightSlateGray,Margin=new Thickness(0,4,0,8)});}
    async Task StabilizeSprites(){if(busy)return;try{if(frames.Count<2){Tell("Нужно минимум два кадра.");return;}int strength=Number(stabilityStrength,1,3),colors=Number(stableColors,16,256),threshold=Number(referenceThreshold,8,128);editor.FinishStroke();clock.Stop();busy=true;IsEnabled=false;Tell("Стабилизирую цвета всей анимации…");var before=frames;var result=await Task.Run(()=>TemporalStabilizer.Compute(before,strength,colors,true,threshold));frames=result;undo.Push(new FrameSetEdit(frames,before,current));changed=true;MarkStudioDirty();RefreshTimeline();Tell("Цвета стабилизированы. Проверьте движение; Ctrl+Z отменит обработку целиком.");}catch(Exception ex){Tell("Стабилизация: "+ex.Message);}finally{busy=false;IsEnabled=true;}}
}
public sealed partial class CutsceneEditor {
    static readonly string[] labelHex={"#3E527E","#2E967D","#669347","#CA8538","#BE555C","#9768BC","#C56CA7","#B6A440","#628FAE","#777F8E"};
    static readonly string[] labelNames={"Синий","Бирюзовый","Зелёный","Оранжевый","Красный","Фиолетовый","Розовый","Жёлтый","Голубой","Серый"};
    readonly ComboBox labelPicker=new ComboBox(),stabilityPicker=new ComboBox(),palettePicker=new ComboBox();
    readonly TextBlock stabilizationLayerName=new TextBlock {TextWrapping=TextWrapping.Wrap,FontWeight=FontWeights.Bold,Foreground=Brushes.MediumAquamarine};
    readonly Slider referenceSlider=new Slider {Minimum=8,Maximum=128,TickFrequency=1,IsSnapToTickEnabled=true,Value=56};readonly TextBlock referenceLabel=new TextBlock {TextWrapping=TextWrapping.Wrap};
    readonly Dictionary<string,TextBox> inlineNames=new Dictionary<string,TextBox>();
    void AddLabelColorControl(Panel panel){panel.Children.Add(new TextBlock {Text="Цвет метки слоя",Margin=new Thickness(0,0,0,4)});for(int i=0;i<labelHex.Length;i++){var row=new StackPanel {Orientation=Orientation.Horizontal};row.Children.Add(new Border {Width=18,Height=12,Background=new SolidColorBrush((Color)ColorConverter.ConvertFromString(labelHex[i])),Margin=new Thickness(0,0,8,0)});row.Children.Add(new TextBlock {Text=labelNames[i],Foreground=Brushes.Black});labelPicker.Items.Add(new ComboBoxItem {Content=row,Tag=labelHex[i]});}labelPicker.Margin=new Thickness(0,0,0,10);panel.Children.Add(labelPicker);labelPicker.SelectionChanged+=(s,e)=>{if(updating||selected==null)return;var item=labelPicker.SelectedItem as ComboBoxItem;if(item!=null)try{SetLayerMetadata(selected,"LabelColor",(string)item.Tag);}catch(Exception ex){Tell(ex.Message);}};}
    void InitializeAnimationControls(){
        var panel=new StackPanel {Margin=new Thickness(10)};inspector.Items.Add(new TabItem {Header="Рябь",Content=new ScrollViewer {Content=panel,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled}});panel.Children.Add(stabilizationLayerName);panel.Children.Add(Hint("Общая палитра и устойчивые цвета во времени. Настройка применяется к выбранной PNG-анимации, исходные кадры остаются в проекте."));
        panel.Children.Add(new TextBlock {Text="Сила стабилизации",Margin=new Thickness(0,5,0,5)});stabilityPicker.ItemsSource=new[]{"0 · Выключена","1 · Мягкая","2 · Обычная","3 · Сильная"};stabilityPicker.Margin=new Thickness(0,0,0,12);panel.Children.Add(stabilityPicker);panel.Children.Add(new TextBlock {Text="Цветов на всю анимацию",Margin=new Thickness(0,0,0,5)});palettePicker.ItemsSource=new[]{16,32,48,64,96,128,256};panel.Children.Add(palettePicker);panel.Children.Add(referenceLabel);panel.Children.Add(referenceSlider);SetupReferenceSlider();
        panel.Children.Add(Hint("Первый кадр сохраняется точно. Неподвижные участки удерживают его рисунок; после настоящего движения опорой становится начало новой позы. Порог — максимальная разница RGB-канала (0…255): выше порог — больше слабых изменений подавляется. Начните с 56. Согласованное движение границ проверяется отдельно. Для сравнения — сила 0."));Button(panel,"Обработать все анимированные слои",async()=>await StabilizeAllLayers());
        stabilityPicker.SelectionChanged+=(s,e)=>{if(updating||selected==null||stabilityPicker.SelectedIndex<0)return;try{CommitLayerValue("Stabilization",stabilityPicker.SelectedIndex);}catch(Exception ex){Tell(ex.Message);}};
        palettePicker.SelectionChanged+=(s,e)=>{if(updating||selected==null||palettePicker.SelectedItem==null)return;try{CommitLayerValue("PaletteSize",(int)palettePicker.SelectedItem);}catch(Exception ex){Tell(ex.Message);}};
        TemporalStabilizer.Completed+=()=>{if(!IsLoaded)return;RefreshView();if(status.Text.StartsWith("Готовится стабилизация",StringComparison.Ordinal)&&selected!=null&&selected.Stabilization>0){var task=TemporalStabilizer.Prepare(selected.Frames,selected.Stabilization,selected.PaletteSize,selected.Loop,selected.ReferenceThreshold);if(task.Status==TaskStatus.RanToCompletion)Tell("Стабилизация готова. Сила 0 — сравнить с оригиналом.");else if(task.IsFaulted)Tell("Не удалось стабилизировать слой: "+task.Exception.GetBaseException().Message);}};
    }
    void SyncAnimationControls(){bool old=updating;updating=true;labelPicker.IsEnabled=selected!=null;referenceSlider.IsEnabled=selected!=null&&!selected.Locked&&selected.Frames.Count>1;referenceSlider.Value=selected==null?56:selected.ReferenceThreshold;referenceLabel.Text="Порог смены цвета: "+referenceSlider.Value.ToString("0")+" / 255";stabilityPicker.IsEnabled=palettePicker.IsEnabled=selected!=null&&!selected.Locked&&selected.Frames.Count>1;labelPicker.SelectedIndex=selected==null?-1:Array.FindIndex(labelHex,c=>string.Equals(c,selected.LabelColor,StringComparison.OrdinalIgnoreCase));stabilityPicker.SelectedIndex=selected==null?0:selected.Stabilization;palettePicker.SelectedItem=selected==null?64:selected.PaletteSize;stabilizationLayerName.Text=selected==null?"Выберите слой":"Слой: "+selected.Name+" · "+selected.Frames.Count+" кадров";updating=old;}
    void OnStabilizationChanged(){SceneRenderer.ClearCache();if(selected!=null&&selected.Stabilization>0&&selected.Frames.Count>1){TemporalStabilizer.Prepare(selected.Frames,selected.Stabilization,selected.PaletteSize,selected.Loop,selected.ReferenceThreshold);Tell("Готовится стабилизация «"+selected.Name+"»… Экспорт дождётся обработки.");}SyncAnimationControls();}
    async Task StabilizeAllLayers(){if(exporting)return;try{var targets=scene.Layers.Where(l=>!l.Locked&&!l.ProceduralLoop&&l.Frames.Count>1).ToList();if(targets.Count==0){Tell("Нет доступных PNG-анимаций. Добавьте анимацию или снимите блокировку L.");return;}EndLiveEdit();Remember();foreach(var layer in targets){layer.Stabilization=2;layer.PaletteSize=64;}ShowLayer();RefreshLayers();RefreshView();Tell("Стабилизирую "+targets.Count+" анимированных слоёв…");await TemporalStabilizer.PrepareScene(Clone(scene),CancellationToken.None);RefreshView();Tell("Стабилизация готова. Сила и палитра — во вкладке «Рябь»; 0 выключает эффект для сравнения.");}catch(Exception ex){Tell("Стабилизация: "+ex.Message);}}
    void SetLayerMetadata(SceneLayer layer,string property,string value){if(exporting||layer==null)return;var field=typeof(SceneLayer).GetField(property);if(Equals(field.GetValue(layer),value))return;var candidate=Clone(scene);field.SetValue(candidate.Layers[scene.Layers.IndexOf(layer)],value);candidate.Validate();Remember();field.SetValue(layer,value);dirty=true;RefreshLayers();ShowLayer();RefreshView();}
    void ClearInlineNames(){foreach(var box in inlineNames.Values)box.Tag=false;inlineNames.Clear();}
    StackPanel CreateInlineLayerName(SceneLayer layer){var stack=new StackPanel {Margin=new Thickness(0,2,4,2)};var title=new TextBlock {Text=layer.Name,TextTrimming=TextTrimming.CharacterEllipsis,ToolTip="Двойной щелчок — переименовать"};var input=new TextBox {Text=layer.Name,Visibility=Visibility.Collapsed,Padding=new Thickness(2),Tag=false};inlineNames[layer.Id]=input;stack.Children.Add(title);stack.Children.Add(input);stack.Children.Add(new TextBlock {Text=layer.Frames.Count+" кадр. · "+layer.Start.ToString("0.##")+"–"+(layer.Start+layer.Duration).ToString("0.##")+" с",FontSize=10,Foreground=Brushes.LightSlateGray});
        title.MouseLeftButtonDown+=(s,e)=>{if(e.ClickCount==2){Select(scene.Layers.FirstOrDefault(l=>l.Id==layer.Id));FocusInlineName();e.Handled=true;}};
        input.PreviewKeyDown+=(s,e)=>{if(e.Key==Key.Enter){FinishInlineName(layer.Id,input,true);e.Handled=true;}if(e.Key==Key.Escape){FinishInlineName(layer.Id,input,false);e.Handled=true;}};input.LostKeyboardFocus+=(s,e)=>{if(Equals(input.Tag,true))FinishInlineName(layer.Id,input,true);};return stack;}
    void FocusInlineName(){if(selected==null)return;EndLiveEdit();layerDragId=null;inspector.SelectedIndex=0;RefreshLayerSelection();TextBox input;if(!inlineNames.TryGetValue(selected.Id,out input))return;var stack=(StackPanel)input.Parent;((TextBlock)stack.Children[0]).Visibility=Visibility.Collapsed;input.Visibility=Visibility.Visible;input.Tag=true;layers.ScrollIntoView(layers.SelectedItem);Dispatcher.BeginInvoke(new Action(()=>{input.Focus();input.SelectAll();}),DispatcherPriority.Input);}
    void FinishInlineName(string id,TextBox input,bool commit){if(!Equals(input.Tag,true))return;input.Tag=false;var layer=scene.Layers.FirstOrDefault(l=>l.Id==id);if(commit&&layer!=null){try{SetLayerMetadata(layer,"Name",string.IsNullOrWhiteSpace(input.Text)?"Слой":input.Text.Trim());}catch(Exception ex){Tell(ex.Message);}}input.Visibility=Visibility.Collapsed;var stack=input.Parent as StackPanel;if(stack!=null)((TextBlock)stack.Children[0]).Visibility=Visibility.Visible;}
    void AddLabelMenu(ContextMenu menu,SceneLayer layer){var colors=new MenuItem {Header="Цвет метки",Foreground=Brushes.Black};for(int n=0;n<labelHex.Length;n++){string hex=labelHex[n];var entry=new MenuItem {Header=labelNames[n],Foreground=Brushes.Black,Icon=new Border {Width=14,Height=14,Background=new SolidColorBrush((Color)ColorConverter.ConvertFromString(hex))}};entry.Click+=(s,e)=>{try{var l=scene.Layers.FirstOrDefault(v=>v.Id==layer.Id);if(l!=null)SetLayerMetadata(l,"LabelColor",hex);}catch(Exception ex){Tell(ex.Message);}};colors.Items.Add(entry);}menu.Items.Add(colors);}
}
}



